package com.rekluzlabs.makokolorize.ui.themeimport android.os.Buildimport androidx.compose.foundation.isSystemInDarkThemeimport androidx.compose.material3.MaterialThemeimport androidx.compose.material3.darkColorSchemeimport androidx.compose.material3.dynamicDarkColorSchemeimport androidx.compose.material3.dynamicLightColorSchemeimport androidx.compose.material3.lightColorSchemeimport androidx.compose.runtime.Composableimport androidx.compose.ui.platform.LocalContextprivate val DarkColorScheme = darkColorScheme(    primary = Purple80,    secondary = PurpleGrey80,    tertiary = Pink80)private val LightColorScheme = lightColorScheme(    primary = Purple40,    secondary = PurpleGrey40,    tertiary = Pink40    /* Other default colors to override    background = Color(0xFFFFFBFE),    surface = Color(0xFFFFFBFE),    onPrimary = Color.White,    onSecondary = Color.White,    onTertiary = Color.White,    onBackground = Color(0xFF1C1B1F),    onSurface = Color(0xFF1C1B1F),    */)@Composablefun MakokolorizeTheme(    darkTheme: Boolean = isSystemInDarkTheme(),    // Dynamic color is available on Android 12+    dynamicColor: Boolean = true,    content: @Composable () -> Unit) {    val colorScheme = when {        dynamicColor && Build.VERSION.SDK_INT >= Build.VERSION_CODES.S -> {            val context = LocalContext.current            if (darkTheme) dynamicDarkColorScheme(context) else dynamicLightColorScheme(context)        }        darkTheme -> DarkColorScheme        else -> LightColorScheme    }    MaterialTheme(        colorScheme = colorScheme,        typography = Typography,        content = content    )}